import{_ as l,I as t,o as n,c as d,b6 as e,j as o,J as i,w as h}from"./chunks/framework.BUXTSoD9.js";const y=JSON.parse('{"title":"تطوير نظام الخدمات المصغرة للتجارة الإلكترونية للمواد الغذائية الطازجة - مشروع عملي","description":"","frontmatter":{},"headers":[],"relativePath":"ar-sa/stage-2/assignments/simple-grocery-microservices/index.md","filePath":"ar-sa/stage-2/assignments/simple-grocery-microservices/index.md"}'),c={name:"ar-sa/stage-2/assignments/simple-grocery-microservices/index.md"},p={style:{margin:"32px 0"}};function b(g,a,k,u,m,f){const r=t("StepBar"),s=t("ClientOnly");return n(),d("div",null,[a[0]||(a[0]=e('<h1 id="تطوير-نظام-الخدمات-المصغرة-للتجارة-الإلكترونية-للمواد-الغذائية-الطازجة-مشروع-عملي" tabindex="-1">تطوير نظام الخدمات المصغرة للتجارة الإلكترونية للمواد الغذائية الطازجة - مشروع عملي <a class="header-anchor" href="#تطوير-نظام-الخدمات-المصغرة-للتجارة-الإلكترونية-للمواد-الغذائية-الطازجة-مشروع-عملي" aria-label="Permalink to “تطوير نظام الخدمات المصغرة للتجارة الإلكترونية للمواد الغذائية الطازجة - مشروع عملي”">​</a></h1><h2 id="نظرة-عامة" tabindex="-1">نظرة عامة <a class="header-anchor" href="#نظرة-عامة" aria-label="Permalink to “نظرة عامة”">​</a></h2><p>يتطلب منك هذا المشروع العملي العمل على أساس مستند متطلبات منتج (PRD) حقيقي، وبناء نظام خدمات مصغرة للتجارة الإلكترونية للمواد الغذائية الطازجة من الصفر. على عكس مشاريع الخدمة الواحدة السابقة، يتم تقسيم الواجهة الخلفية لهذا المشروع إلى خدمات مستقلة متعددة حسب الأعمال، وتوحيدها للخارج من خلال بوابة API. ستتعلم كيفية تصميم حدود الخدمات وكيفية التعامل مع مشاكل تناسق البيانات عبر الخدمات.</p><p>هذا هو مشروع Stage 2 التطبيقي الشامل. هندسة الخدمات المصغرة شائعة جداً في العمل الفعلي، وبعد إتقان الأفكار الأساسية لتقسيم الخدمات وتوجيه البوابة، ستتمكن من التعامل مع تصميم أنظمة خلفية أكثر تعقيداً.</p><h2 id="المعارف-المسبقة" tabindex="-1">المعارف المسبقة <a class="header-anchor" href="#المعارف-المسبقة" aria-label="Permalink to “المعارف المسبقة”">​</a></h2><p>قبل البدء في هذا المشروع، يجب أن تكون قد أتقنت المحتوى التالي:</p><ul><li>تصميم واجهات الويب واستخدام مكتبات المكونات (<a href="./../../frontend/ui-design/">تصميم واجهة المستخدم</a>، <a href="./../../frontend/modern-component-library/">المكتبة الحديثة للمكونات</a>)</li><li>تصميم وتطوير واجهات البرمجيات الخلفية (<a href="./../../backend/ai-interface-code/">كتابة كود الواجهات</a>)</li><li>أساسيات قواعد البيانات و Supabase (<a href="./../../backend/database-supabase/">من قاعدة البيانات إلى Supabase</a>)</li><li>سير عمل Git والنشر (<a href="./../../backend/git-workflow/">Git و GitHub</a>، <a href="./../../backend/zeabur-deployment/">نشر تطبيقات الويب</a>)</li></ul><h2 id="أهداف-التعلم" tabindex="-1">أهداف التعلم <a class="header-anchor" href="#أهداف-التعلم" aria-label="Permalink to “أهداف التعلم”">​</a></h2><p>بعد إكمال هذا المشروع العملي، ستتمكن من:</p><ol><li>قراءة PRD واستخراج قائمة مهام تطوير نظام الخدمات المصغرة</li><li>تقسيم حدود الخدمات حسب مجال الأعمال (المصادقة، المنتجات، المخزون، الطلبات)</li><li>تصميم وتنفيذ مسارات بوابة API</li><li>التعامل مع مشاكل خصم المخزون وتناسق الطلبات عبر الخدمات</li><li>إكمال الاختبار الشامل من طرف إلى طرف وتسليم نموذج أولي للخدمات المصغرة قابل للعرض</li></ol><h2 id="مقدمة-المشروع" tabindex="-1">مقدمة المشروع <a class="header-anchor" href="#مقدمة-المشروع" aria-label="Permalink to “مقدمة المشروع”">​</a></h2><p>المنتج الذي ستبنيه هو نظام خدمات مصغرة للتجارة الإلكترونية للمواد الغذائية الطازجة:</p><table tabindex="0"><thead><tr><th>النظام الفرعي</th><th>المسؤولية</th></tr></thead><tbody><tr><td><strong>واجهة المستخدم</strong></td><td>تصفح المنتجات، تقديم الطلبات، عرض الطلبات</td></tr><tr><td><strong>واجهة الإدارة</strong></td><td>إدارة المنتجات، إدارة المخزون، إدارة الطلبات</td></tr></tbody></table><p>يتم تقسيم الواجهة الخلفية حسب الأعمال إلى الخدمات التالية:</p><table tabindex="0"><thead><tr><th>الخدمة</th><th>المسؤولية</th></tr></thead><tbody><tr><td><strong>API Gateway</strong></td><td>مدخل موحد، توجيه الطلبات، التحقق من المصادقة</td></tr><tr><td><strong>Auth Service</strong></td><td>تسجيل المستخدمين، تسجيل الدخول، إصدار JWT</td></tr><tr><td><strong>Catalog Service</strong></td><td>إدارة معلومات المنتجات</td></tr><tr><td><strong>Inventory Service</strong></td><td>إدارة كميات المخزون</td></tr><tr><td><strong>Order Service</strong></td><td>إنشاء الطلبات، إدارة الحالات</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">مدخل PRD</p><p>مستند متطلبات هذا المشروع متاح على GitHub: <a href="https://github.com/datawhalechina/easy-vibe/blob/main/docs/zh-cn/stage-2/assignments/simple-grocery-microservices/PRD.md" target="_blank" rel="noreferrer">عرض PRD</a></p></div>',16)),o("div",p,[i(s,null,{default:h(()=>[i(r,{active:0,items:[{title:"تحليل المتطلبات",description:"قراءة PRD وتوضيح تقسيم الخدمات والصفحات وسلسلة المعاملات"},{title:"بناء الهيكل",description:"إنشاء الواجهة الأمامية والبوابة وهياكل الخدمات"},{title:"التطوير التكراري",description:"إضافة الواجهات لكل وحدة وإصلاح تناسق المخزون والطلبات"},{title:"الاختبار والنشر",description:"الاختبار الشامل من طرف إلى طرف والنشر والتحضير للعرض"}]})]),_:1})]),a[1]||(a[1]=e(`<h2 id="الجزء-الأول-تحليل-المتطلبات" tabindex="-1">الجزء الأول: تحليل المتطلبات <a class="header-anchor" href="#الجزء-الأول-تحليل-المتطلبات" aria-label="Permalink to “الجزء الأول: تحليل المتطلبات”">​</a></h2><h3 id="_1-1-قراءة-prd" tabindex="-1">1.1 قراءة PRD <a class="header-anchor" href="#_1-1-قراءة-prd" aria-label="Permalink to “1.1 قراءة PRD”">​</a></h3><p>افتح مستند PRD، وركز على الإجابة عن الأسئلة التالية:</p><ul><li>كيف يتم تقسيم الخدمات؟ ما هي حدود مسؤولية كل خدمة؟</li><li>ما هي الصفحات في واجهة المستخدم وواجهة الإدارة على التوالي؟</li><li>ما هي استراتيجية خصم المخزون بعد تقديم الطلب؟ كيف يتم التعامل مع النجاح / الفشل / انتهاء المهلة؟</li><li>ما هي القدرات المعقدة التي يتم تأجيلها في الإصدار الأول (مثل المعاملات الموزعة، طوابير الرسائل)؟</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>إذا لم تكن لديك إجابات واضحة على الأسئلة أعلاه، لا تبدأ في كتابة الكود. سوء فهم المتطلبات هو السبب الأكثر شيوعاً لإعادة العمل.</p></div><h3 id="_1-2-تأكيد-بنية-النظام" tabindex="-1">1.2 تأكيد بنية النظام <a class="header-anchor" href="#_1-2-تأكيد-بنية-النظام" aria-label="Permalink to “1.2 تأكيد بنية النظام”">​</a></h3><div class="language-mermaid"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  prd[&quot;PRD&quot;] --&gt; fe[&quot;الصفحات الأمامية&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  fe --&gt; gw[&quot;API Gateway&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; auth[&quot;Auth Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; catalog[&quot;Catalog Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; inventory[&quot;Inventory Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gw --&gt; order[&quot;Order Service&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  order --&gt; inventory</span></span></code></pre></div><h2 id="الجزء-الثاني-بناء-هيكل-المشروع" tabindex="-1">الجزء الثاني: بناء هيكل المشروع <a class="header-anchor" href="#الجزء-الثاني-بناء-هيكل-المشروع" aria-label="Permalink to “الجزء الثاني: بناء هيكل المشروع”">​</a></h2><h3 id="_2-1-إنشاء-هيكل-المشروع" tabindex="-1">2.1 إنشاء هيكل المشروع <a class="header-anchor" href="#_2-1-إنشاء-هيكل-المشروع" aria-label="Permalink to “2.1 إنشاء هيكل المشروع”">​</a></h3><p>مرجع لموجه الأوامر:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>بناءً على PRD الحالي، ساعدني في إنشاء هيكل مشروع نظام الخدمات المصغرة للتجارة الإلكترونية للمواد الغذائية الطازجة.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>المتطلبات:</span></span>
<span class="line"><span>1. إنشاء هيكل واجهة المستخدم وواجهة الإدارة الأمامية</span></span>
<span class="line"><span>2. إنشاء خمسة أدلة: api-gateway و auth-service و catalog-service و inventory-service و order-service</span></span>
<span class="line"><span>3. كل خدمة تقوم فقط بإنشاء مدخل أدنى قابل للتشغيل</span></span>
<span class="line"><span>4. عدم الاتصال بقاعدة بيانات حقيقية أو نظام دفع في البداية</span></span></code></pre></div><h3 id="_2-2-التحقق-من-هيكل-المشروع" tabindex="-1">2.2 التحقق من هيكل المشروع <a class="header-anchor" href="#_2-2-التحقق-من-هيكل-المشروع" aria-label="Permalink to “2.2 التحقق من هيكل المشروع”">​</a></h3><p>تحقق من كل عنصر:</p><ul><li>[ ] هيكل أدلة الخدمات الخمسة واضح</li><li>[ ] يمكن بدء API Gateway وإعادة توجيه الطلبات</li><li>[ ] واجهات الفحص الصحي لكل خدمة متاحة</li><li>[ ] يمكن الوصول إلى صفحات واجهة المستخدم وواجهة الإدارة</li></ul><h2 id="الجزء-الثالث-التطوير-التكراري" tabindex="-1">الجزء الثالث: التطوير التكراري <a class="header-anchor" href="#الجزء-الثالث-التطوير-التكراري" aria-label="Permalink to “الجزء الثالث: التطوير التكراري”">​</a></h2><h3 id="_3-1-التقدم-حسب-الوحدات" tabindex="-1">3.1 التقدم حسب الوحدات <a class="header-anchor" href="#_3-1-التقدم-حسب-الوحدات" aria-label="Permalink to “3.1 التقدم حسب الوحدات”">​</a></h3><ol><li><strong>API Gateway</strong>: تكوين المسارات، وسيط التحقق من JWT</li><li><strong>Auth Service</strong>: التسجيل، تسجيل الدخول، إصدار JWT</li><li><strong>Catalog Service</strong>: عمليات CRUD للمنتجات، استعلام القائمة</li><li><strong>Inventory Service</strong>: استعلام المخزون، خصم المخزون</li><li><strong>Order Service</strong>: إنشاء الطلبات، تدفق الحالات، الربط مع المخزون</li><li><strong>واجهة الإدارة</strong>: إدارة المنتجات، إدارة المخزون، إدارة الطلبات</li></ol><h3 id="_3-2-الفحص-الذاتي-للوحدات" tabindex="-1">3.2 الفحص الذاتي للوحدات <a class="header-anchor" href="#_3-2-الفحص-الذاتي-للوحدات" aria-label="Permalink to “3.2 الفحص الذاتي للوحدات”">​</a></h3><table tabindex="0"><thead><tr><th>عنصر الفحص</th><th>طريقة التحقق</th></tr></thead><tbody><tr><td>مسارات البوابة</td><td>هل يتم إعادة توجيه واجهات كل خدمة بشكل صحيح عبر البوابة</td></tr><tr><td>عزل الصلاحيات</td><td>هل واجهات المستخدم وواجهة الإدارة معزولة</td></tr><tr><td>توافق البيانات</td><td>هل بيانات المنتجات والمخزون متزامنة</td></tr><tr><td>حلقة المعاملات</td><td>بعد تقديم الطلب، هل خصم المخزون وحالة الطلب متسقة</td></tr><tr><td>معالجة الفشل</td><td>عند عدم كفاية المخزون أو انتهاء المهلة، هل توجد آلية تعويض</td></tr></tbody></table><h2 id="الجزء-الرابع-الاختبار-والنشر" tabindex="-1">الجزء الرابع: الاختبار والنشر <a class="header-anchor" href="#الجزء-الرابع-الاختبار-والنشر" aria-label="Permalink to “الجزء الرابع: الاختبار والنشر”">​</a></h2><h3 id="_4-1-اختبار-من-طرف-إلى-طرف" tabindex="-1">4.1 اختبار من طرف إلى طرف <a class="header-anchor" href="#_4-1-اختبار-من-طرف-إلى-طرف" aria-label="Permalink to “4.1 اختبار من طرف إلى طرف”">​</a></h3><p>تحقق من السيناريوهات التالية على الأقل:</p><ul><li>تصفح المنتجات ← إضافة إلى سلة التسوق ← تقديم طلب ← عرض الطلب</li><li>المسؤول ← إضافة منتج ← تحديث المخزون ← عرض الطلب</li></ul><h2 id="المخرجات-المطلوبة" tabindex="-1">المخرجات المطلوبة <a class="header-anchor" href="#المخرجات-المطلوبة" aria-label="Permalink to “المخرجات المطلوبة”">​</a></h2><p>بعد إكمال هذا المشروع، يجب عليك تقديم المحتوى التالي:</p><ul><li>[ ] رابط عرض عبر الإنترنت قابل للوصول</li><li>[ ] رابط مستودع الكود المصدري (يتضمن README)</li><li>[ ] مستند PRD</li><li>[ ] لقطات شاشة للصفحات الرئيسية (قائمة المنتجات، صفحة الطلب، صفحة الطلبات، لوحة الإدارة)</li><li>[ ] فيديو عرض مدته 60 ثانية</li></ul><h2 id="معايير-التقييم" tabindex="-1">معايير التقييم <a class="header-anchor" href="#معايير-التقييم" aria-label="Permalink to “معايير التقييم”">​</a></h2><table tabindex="0"><thead><tr><th>البُعد</th><th>المتطلبات الأساسية</th><th>المتطلبات المتقدمة</th></tr></thead><tbody><tr><td>توافق PRD</td><td>الصفحات والوظائف وتقسيم الخدمات يتوافق بشكل أساسي مع PRD</td><td>القدرة على شرح أسباب تقسيم الخدمات بوضوح</td></tr><tr><td>حلقة المنتج</td><td>تصفح ← تقديم طلب ← خصم مخزون ← عرض الطلب يعمل بشكل كامل</td><td>عند انتهاء مهلة الطلب أو عدم كفاية المخزون توجد آلية تعويض</td></tr><tr><td>بنية الخدمات</td><td>يمكن بدء كل خدمة بشكل مستقل والوصول إليها بشكل موحد عبر البوابة</td><td>الاتصال بين الخدمات لديه معالجة أخطاء وإعادة محاولة</td></tr><tr><td>قدرات لوحة الإدارة</td><td>إدارة المنتجات والمخزون والطلبات قابلة للتشغيل</td><td>واجهة الإدارة لديها إحصائيات بيانات</td></tr><tr><td>اكتمال الهندسة</td><td>تم ربط سلسلة الواجهة الأمامية والبوابة والخدمات وقاعدة البيانات</td><td>يوجد Docker Compose أو تنسيق مشابه</td></tr></tbody></table><h2 id="المراجع" tabindex="-1">المراجع <a class="header-anchor" href="#المراجع" aria-label="Permalink to “المراجع”">​</a></h2><ul><li><a href="./../../frontend/ui-design/">تصميم واجهة المستخدم</a></li><li><a href="./../../frontend/modern-component-library/">تحديث واجهتك باستخدام المكتبة الحديثة للمكونات</a></li><li><a href="./../../backend/database-supabase/">من قاعدة البيانات إلى Supabase</a></li><li><a href="./../../backend/ai-interface-code/">كتابة كود الواجهات بمساعدة النماذج اللغوية الكبيرة</a></li><li><a href="./../../backend/git-workflow/">سير عمل Git و GitHub</a></li><li><a href="./../../backend/zeabur-deployment/">نشر تطبيقات الويب</a></li></ul>`,30))])}const P=l(c,[["render",b]]);export{y as __pageData,P as default};
